// Convert array of search terms into separate items
const searchTerms = ['saree'];

return searchTerms.map(term => ({
  json: {
    searchTerm: term
  }
}));

// ============================================================================
// BUILD FACEBOOK API REQUEST - WITH PAGINATION SUPPORT
// Updated: Feb 12, 2026
// ============================================================================

const inputData = $input.first().json;
const afterCursor = inputData.afterCursor || null;
const searchTerm = inputData.searchTerm || inputData.searchTerms;
const accessToken = 'EAATGHDjCPo0BQtmRpCVZAu2fv1V0MYZCJPWdqkoSa3C5I8ZCoJyAOF6sFUGmRqXpzXWcqZBsz91B8ZAjZAhU437wsMxJgD4dOnp2h3MBL0z93PmvLuJAvZAPUJqZBTZCPPlYLTDbdWp6dANHUYrZC7yXB86JwFDdZAqwVZBq61tX7yaXgCexnKYDEleAPb1Vit2vb6UJcvPXLOgCqD1xMZAuHcJgZD';

const apiBaseUrl = 'https://graph.facebook.com/v21.0/ads_archive';

const params = {
  access_token: accessToken,
  search_terms: searchTerm,
  ad_reached_countries: JSON.stringify(['IN']),
  ad_active_status: 'ACTIVE',
  limit: '100',
  fields: 'id,page_id,page_name,ad_creative_bodies,ad_creative_link_captions,ad_creative_link_titles,ad_snapshot_url,ad_delivery_start_time,ad_delivery_stop_time,currency,spend'
};

if (afterCursor) {
  params.after = afterCursor;
  console.log(`📄 PAGINATION REQUEST for "${searchTerm}" | Cursor: ${afterCursor.substring(0, 30)}...`);
} else {
  console.log(`🔍 INITIAL REQUEST for "${searchTerm}"`);
}

const queryParts = [];
for (const key in params) {
  if (params.hasOwnProperty(key) && params[key] !== undefined && params[key] !== null) {
    queryParts.push(encodeURIComponent(key) + '=' + encodeURIComponent(params[key]));
  }
}

const fullUrl = apiBaseUrl + '?' + queryParts.join('&');

return [{
  json: {
    url: fullUrl,
    searchTerm: searchTerm,
    isPaginationRequest: !!afterCursor,
    timestamp: new Date().toISOString()
  }
}];

// ============================================================================
// PARSE RESULTS NODE - WITH PAGINATION SUPPORT  
// Reference: https://docs.n8n.io/code/code-node/
// Updated: Feb 12, 2026
// ============================================================================

const response = $input.first().json;
const items = [];

try {
  if (response.error) {
    const errorMsg = response.error.error_user_msg || response.error.message || 'Unknown API error';
    console.error('❌ Facebook API Error:', errorMsg, 'Code:', response.error.code);
    return [{ 
      json: { 
        error: true, 
        errorMessage: errorMsg,
        errorCode: response.error.code,
        errorType: response.error.type
      } 
    }];
  }

  const ads = response.data || [];
  const paging = response.paging || {};
  const hasMore = !!(paging.cursors && paging.cursors.after);
  const nextCursor = hasMore ? paging.cursors.after : null;

  console.log(`📄 Pagination Info: hasMore=${hasMore}, nextCursor=${nextCursor ? nextCursor.substring(0, 20) + '...' : 'null'}`);

  if (!Array.isArray(ads) || ads.length === 0) {
    console.log('⚠️ No ads found in this batch');
    return [{ 
      json: { 
        noResults: true,
        hasMore: hasMore,
        nextCursor: nextCursor
      } 
    }];
  }

  console.log(`📊 Processing ${ads.length} ads from Facebook Ad Library API`);

  const OBVIOUS_IRRELEVANT = /\b(watch|laikrodžiai|lithuania|tauras|mobile phone|smartphone|laptop|computer|electronics|gadget|food|restaurant|hotel|travel package|insurance|loan|père|kathy|novel|drama|story|fiction|book|game|gaming|astrology|horoscope|casino|betting)\b/gi;

  function extractContactInfo(ad) {
    const contact = {
      business_website: null,
      whatsapp_url: null,
      whatsapp_number: null,
      instagram_url: null,
      facebook_url: null,
      phone_number: null,
      url_type: 'UNKNOWN'
    };

    const allText = [
      ad.page_name || '',
      ...(ad.ad_creative_bodies || []),
      ...(ad.ad_creative_link_captions || []),
      ...(ad.ad_creative_link_descriptions || []),
      ...(ad.ad_creative_link_titles || [])
    ].join(' ');

    const waUrlMatch = allText.match(/(?:wa\.me\/|api\.whatsapp\.com\/send\?phone=)(\+?91)?([6-9]\d{9})/i);
    if (waUrlMatch) {
      const number = waUrlMatch[2];
      contact.whatsapp_number = number;
      contact.phone_number = number;
      contact.whatsapp_url = `https://wa.me/91${number}`;
    }

    if (!contact.whatsapp_number) {
      const phonePatterns = [
        /(?:\+91[-\s]?|91[-\s]?|0)?([6-9]\d{9})\b/g,
        /([6-9]\d{2})[-\s]?(\d{3})[-\s]?(\d{4})/g
      ];

      for (const pattern of phonePatterns) {
        const matches = allText.matchAll(pattern);
        for (const match of matches) {
          let number;
          if (match.length === 2) {
            number = match[1];
          } else if (match.length === 4) {
            number = match[1] + match[2] + match[3];
          }

          if (number && /^[6-9]\d{9}$/.test(number)) {
            contact.phone_number = number;
            contact.whatsapp_number = number;
            contact.whatsapp_url = `https://wa.me/91${number}`;
            break;
          }
        }
        if (contact.whatsapp_number) break;
      }
    }

    const urlRegex = /(https?:\/\/[^\s<>"{}|\\^`\[\]]+)/gi;
    const foundUrls = allText.match(urlRegex) || [];

    for (const url of foundUrls) {
      const lowerUrl = url.toLowerCase();

      if (lowerUrl.includes('facebook.com/ads/archive')) {
        continue;
      }

      if (lowerUrl.includes('instagram.com/')) {
        const handleMatch = url.match(/instagram\.com\/([a-zA-Z0-9._]+)/);
        if (handleMatch && handleMatch[1] && !handleMatch[1].includes('p/')) {
          contact.instagram_url = url;
        }
      }
      else if (lowerUrl.includes('facebook.com/')) {
        contact.facebook_url = url;
      }
      else if (lowerUrl.includes('wa.me') || lowerUrl.includes('whatsapp')) {
        contact.whatsapp_url = url;
        if (!contact.whatsapp_number) {
          const waNum = url.match(/wa\.me\/(?:\+?91)?([6-9]\d{9})/i);
          if (waNum) {
            contact.whatsapp_number = waNum[1];
            contact.phone_number = waNum[1];
          }
        }
      }
      else if (!contact.business_website) {
        contact.business_website = url;
      }
    }

    if (!contact.business_website) {
      const domainMatch = allText.match(/\b([a-z0-9-]+\.(com|in|co\.in|org|net))\b/i);
      if (domainMatch && domainMatch[1]) {
        const domain = domainMatch[1].toLowerCase();
        if (!domain.includes('instagram') && !domain.includes('facebook') && !domain.includes('youtube')) {
          contact.business_website = `https://${domainMatch[1]}`;
        }
      }
    }

    if (!contact.business_website && !contact.whatsapp_url && !contact.instagram_url && ad.page_id) {
      contact.facebook_url = `https://www.facebook.com/${ad.page_id}`;
    }

    if (contact.business_website) {
      contact.url_type = 'WEBSITE';
    } else if (contact.whatsapp_url) {
      contact.url_type = 'WHATSAPP';
    } else if (contact.instagram_url) {
      contact.url_type = 'INSTAGRAM';
    } else if (contact.facebook_url) {
      contact.url_type = 'FACEBOOK_PAGE';
    }

    return contact;
  }

  let acceptedCount = 0;
  let filteredCount = 0;

  for (const ad of ads) {
    if (!ad || typeof ad !== 'object' || !ad.id) {
      continue;
    }

    const pageName = (ad.page_name || '').toLowerCase();

    if (OBVIOUS_IRRELEVANT.test(pageName)) {
      filteredCount++;
      continue;
    }

    const contact = extractContactInfo(ad);

    let landingUrl = contact.business_website || 
                     contact.whatsapp_url || 
                     contact.instagram_url || 
                     contact.facebook_url || 
                     ad.ad_snapshot_url;

    acceptedCount++;

    items.push({
      json: {
        page_id: ad.page_id || 'unknown',
        page_name: ad.page_name || 'Unknown Business',
        ad_id: ad.id || String(Date.now()),
        ad_snapshot_url: ad.ad_snapshot_url || '',
        ad_creative_bodies: ad.ad_creative_bodies || [],
        ad_creative_link_url: landingUrl,
        business_website: contact.business_website,
        whatsapp_url: contact.whatsapp_url,
        whatsapp_number: contact.whatsapp_number,
        instagram_url: contact.instagram_url,
        facebook_url: contact.facebook_url,
        phone_number: contact.phone_number,
        url_type: contact.url_type,
        ad_delivery_start_time: ad.ad_delivery_start_time || null,
        ad_delivery_stop_time: ad.ad_delivery_stop_time || null,
        currency: ad.currency || 'INR',
        spend: ad.spend || null,
        scraped_at: new Date().toISOString(),
        filter_passed: true,
        search_term_used: $input.first().json.searchTerm || 'unknown',
        _pagination_hasMore: hasMore,
        _pagination_nextCursor: nextCursor
      }
    });
  }

  console.log(`✅ Accepted: ${acceptedCount} | ❌ Filtered: ${filteredCount} | Total: ${ads.length}`);
  console.log(`📄 This page has ${hasMore ? 'MORE' : 'NO MORE'} results`);

  return items;

} catch (error) {
  console.error('Parse error:', error.message, error.stack);
  return [{ 
    json: { 
      error: true, 
      errorMessage: `Parse error: ${error.message}`,
      errorStack: error.stack
    } 
  }];
}

// ============================================================================
// AGGREGATE BY PAGE NODE - WITH PAGINATION PASSTHROUGH
// Reference: https://docs.n8n.io/code/code-node/
// Updated: Feb 12, 2026
// ============================================================================

const ads = $input.all();
const pageMap = new Map();

let paginationInfo = {
  hasMore: false,
  nextCursor: null,
  searchTerm: null
};

for (const item of ads) {
  const ad = item.json;

  if (ad._pagination_hasMore !== undefined) {
    paginationInfo.hasMore = ad._pagination_hasMore;
    paginationInfo.nextCursor = ad._pagination_nextCursor;
    paginationInfo.searchTerm = ad.search_term_used;
  }

  const pid = ad.page_id;

  if (!pid || pid === 'unknown') continue;

  if (!pageMap.has(pid)) {
    pageMap.set(pid, {
      page_id: pid,
      page_name: ad.page_name,
      ad_count: 0,
      sample_ad: ad,
      earliest_start: ad.ad_delivery_start_time,
      all_bodies: [],
      business_website: ad.business_website,
      whatsapp_url: ad.whatsapp_url,
      whatsapp_number: ad.whatsapp_number,
      instagram_url: ad.instagram_url,
      facebook_url: ad.facebook_url,
      phone_number: ad.phone_number,
      url_type: ad.url_type,
      landing_url: ad.business_website || ad.whatsapp_url || ad.instagram_url || ad.facebook_url
    });
  }

  const page = pageMap.get(pid);
  page.ad_count++;

  if (ad.business_website && !page.business_website) {
    page.business_website = ad.business_website;
    page.landing_url = ad.business_website;
  }
  if (ad.whatsapp_url && !page.whatsapp_url) {
    page.whatsapp_url = ad.whatsapp_url;
  }
  if (ad.whatsapp_number && !page.whatsapp_number) {
    page.whatsapp_number = ad.whatsapp_number;
    page.phone_number = ad.whatsapp_number;
  }

  if (ad.ad_delivery_start_time) {
    if (!page.earliest_start || ad.ad_delivery_start_time < page.earliest_start) {
      page.earliest_start = ad.ad_delivery_start_time;
    }
  }

  if (Array.isArray(ad.ad_creative_bodies)) {
    page.all_bodies.push(...ad.ad_creative_bodies);
  }
}

const output = [];
for (const [pid, page] of pageMap.entries()) {
  page._pagination_hasMore = paginationInfo.hasMore;
  page._pagination_nextCursor = paginationInfo.nextCursor;
  page._pagination_searchTerm = paginationInfo.searchTerm;

  output.push({ json: page });
}

console.log(`📊 Aggregated ${output.length} unique pages`);
console.log(`📄 Pagination: hasMore=${paginationInfo.hasMore}, cursor=${paginationInfo.nextCursor ? paginationInfo.nextCursor.substring(0, 20) + '...' : 'null'}`);

return output.length > 0 ? output : [{ json: { noPages: true } }];

// ============================================================================
// PREPARE FOR SCORING NODE - COMPLETE REWRITE
// Architecture: Receives COMPLETE data from Merge (Append mode)
// Input Sources:
//   - "Combine HTML With Page Data" (WEBSITE branch) - has HTML + page data
//   - "Skip HTML Fetch" (non-WEBSITE branch) - has skip flag + page data
// Mode: Run Once for Each Item ✅
// Updated: Feb 12, 2026
// ============================================================================

// Access current item (data is already complete from Merge node)
const pageData = $json;

// Validate required fields exist
const requiredFields = ['page_id', 'page_name', 'url_type'];
const missingFields = requiredFields.filter(field => !pageData[field]);

if (missingFields.length > 0) {
  console.error(`❌ Missing required fields for item: ${missingFields.join(', ')}`);
  return {
    json: {
      error: true,
      error_reason: `Missing required fields: ${missingFields.join(', ')}`,
      page_name: pageData.page_name || 'Unknown',
      page_id: pageData.page_id || 'Unknown'
    }
  };
}

// Determine data source for logging
const dataSource = pageData._from_website_branch 
  ? 'WEBSITE (HTML fetched)' 
  : pageData._html_fetch_skipped 
    ? 'NON-WEBSITE (HTML skipped)' 
    : 'UNKNOWN';

// Log processing info
console.log('━'.repeat(60));
console.log(`📋 Preparing: "${pageData.page_name}"`);
console.log(`   Page ID: ${pageData.page_id}`);
console.log(`   URL Type: ${pageData.url_type}`);
console.log(`   Source: ${dataSource}`);
console.log(`   HTML Length: ${pageData.html_length || 0} chars`);
console.log(`   HTML Fetch Error: ${pageData.html_fetch_error || false}`);
console.log(`   Ad Count: ${pageData.ad_count || 0}`);
console.log('━'.repeat(60));

// Validate HTML fields exist (should be added by previous nodes)
if (pageData.html_content === undefined) {
  console.warn(`⚠️ Missing html_content field for "${pageData.page_name}" - adding empty string`);
  pageData.html_content = '';
}

if (pageData.html_length === undefined) {
  console.warn(`⚠️ Missing html_length field for "${pageData.page_name}" - calculating from content`);
  pageData.html_length = (pageData.html_content || '').length;
}

if (pageData.html_fetch_error === undefined) {
  pageData.html_fetch_error = false;
}

if (pageData.html_fetch_attempted === undefined) {
  pageData.html_fetch_attempted = pageData.url_type === 'WEBSITE';
}

// Ensure all_bodies is an array (required for scoring)
if (!Array.isArray(pageData.all_bodies)) {
  console.warn(`⚠️ all_bodies is not an array for "${pageData.page_name}" - converting`);
  pageData.all_bodies = pageData.all_bodies ? [pageData.all_bodies] : [];
}

// Data is already prepared - pass through with validation complete
return {
  json: {
    // Pass through ALL fields from merged data
    page_id: pageData.page_id,
    page_name: pageData.page_name,
    ad_count: pageData.ad_count,
    sample_ad: pageData.sample_ad,
    earliest_start: pageData.earliest_start,
    all_bodies: pageData.all_bodies,
    business_website: pageData.business_website,
    whatsapp_url: pageData.whatsapp_url,
    whatsapp_number: pageData.whatsapp_number,
    instagram_url: pageData.instagram_url,
    facebook_url: pageData.facebook_url,
    phone_number: pageData.phone_number,
    url_type: pageData.url_type,
    landing_url: pageData.landing_url,

    // Pagination fields
    _pagination_hasMore: pageData._pagination_hasMore,
    _pagination_nextCursor: pageData._pagination_nextCursor,
    _pagination_searchTerm: pageData._pagination_searchTerm,

    // HTML fields (already added by previous nodes)
    html_content: pageData.html_content,
    html_length: pageData.html_length,
    html_fetch_error: pageData.html_fetch_error,
    html_fetch_attempted: pageData.html_fetch_attempted,

    // Source tracking fields (for debugging)
    _from_website_branch: pageData._from_website_branch || false,
    _html_fetch_skipped: pageData._html_fetch_skipped || false,
    _html_source: pageData._html_source || 'UNKNOWN',

    // Add metadata for scoring node
    _data_prepared_at: new Date().toISOString(),
    _data_complete: true
  }
};

// Mode: Run Once for Each Item ✅
const pageData = $json;

// Deep clone to ensure plain object structure
const clonedData = JSON.parse(JSON.stringify(pageData));

// Add skip fields
clonedData._html_fetch_skipped = true;
clonedData.html_content = '';
clonedData.html_length = 0;

return {
  json: clonedData
};

// ============================================================================
// SCORE & FILTER NODE - FIXED FOR SEQUENTIAL PROCESSING
// Reference: https://docs.n8n.io/code/code-node/
// Mode: Run Once for Each Item ✅ (CRITICAL)
// Updated: Feb 12, 2026
// ============================================================================

console.log('='.repeat(80));
console.log('🚀 SCORE & FILTER NODE STARTED');
console.log('='.repeat(80));

// Access data from current input item (prepared by "Prepare for Scoring" node)
const pd = $input.item.json;

console.log('📊 Page Data Loaded:');
console.log(`   Page Name: "${pd.page_name}"`);
console.log(`   Page ID: ${pd.page_id}`);
console.log(`   Ad Count: ${pd.ad_count}`);
console.log(`   URL Type: ${pd.url_type}`);
console.log(`   HTML Length: ${pd.html_length || 0}`);

// Extract HTML
const html = pd.html_content || '';
const htmlFetchError = pd.html_fetch_error || false;

function join(arr) {
  return Array.isArray(arr) ? arr.filter(x => x && typeof x === 'string').join(' ') : '';
}

const pageName = pd.page_name || '';
const allBodies = join(pd.all_bodies);
const allText = [pageName, allBodies, html].join(' ');

console.log('📝 Text Analysis:');
console.log(`   Page Name: ${pageName.length} chars`);
console.log(`   Ad Bodies: ${allBodies.length} chars`);
console.log(`   HTML: ${html.length} chars`);
console.log(`   Total Text: ${allText.length} chars`);

const OBVIOUS_IRRELEVANT = /\b(watch|laikrodžiai|lithuania|tauras|mobile phone|smartphone|laptop|computer|electronics|gadget|food|restaurant|hotel|travel package|insurance|loan|père|kathy|novel|drama|story|fiction|book|game|gaming|astrology|horoscope|casino|betting)\b/gi;

const pageNameLower = pageName.toLowerCase();
const isObviouslyIrrelevant = OBVIOUS_IRRELEVANT.test(pageNameLower);

if (isObviouslyIrrelevant) {
  console.log(`❌ REJECTED: "${pd.page_name}" - Obviously irrelevant category`);
  return [{ 
    json: { 
      filtered: true, 
      reason: `Irrelevant category: ${pageNameLower}` 
    } 
  }];
}

console.log(`✅ PASSED MINIMAL FILTER: "${pd.page_name}"`);

const WA_NUMBER = /\b[6-9]\d{9}\b/g;
const WA_KEYWORD = /whatsapp|wa\.me|click\.to\.whatsapp/gi;
const hasWANumber = WA_NUMBER.test(allText) || !!pd.whatsapp_number;
const hasWAKeyword = WA_KEYWORD.test(allText) || !!pd.whatsapp_url;
const hasWhatsApp = hasWANumber || hasWAKeyword || !!pd.phone_number;

const PRICE_SPECIFIC = /(rs\.?|₹)\s*\d+|price[:\s]*\d+/gi;
const PRICE_DM = /dm\s*(for|to\s*get)?\s*price|comment\s*(for|to\s*get)?\s*(price|detail|link)|whatsapp\s*for\s*price|message\s*for\s*price/gi;
const hasSpecificPrice = PRICE_SPECIFIC.test(allText);
const hasDMPrice = PRICE_DM.test(allText);
const hasPricing = hasSpecificPrice || hasDMPrice;

const hasCommercialWebsite = !!pd.business_website;

const LOCATION = /\b(jaipur|delhi|mumbai|surat|ahmedabad|bangalore|bengaluru|hyderabad|chennai|kolkata|pune|lucknow|kanpur|nagpur|indore|bhopal|chandigarh)\b/gi;
const JAIPUR = /\b(jaipur|pink city)\b/gi;
const hasLocation = LOCATION.test(allText);
const hasJaipur = JAIPUR.test(allText);

const PIXEL = /(fbq\(|fbevents)/gi;
const hasPixel = html.length > 0 ? PIXEL.test(html) : false;

const hasInstagram = !!pd.instagram_url;
const hasFacebookPage = !!pd.facebook_url;

console.log('🔍 Quality Signals:');
console.log(`   WhatsApp: ${hasWhatsApp}`);
console.log(`   Website: ${hasCommercialWebsite}`);
console.log(`   Pricing: ${hasPricing}`);
console.log(`   Pixel: ${hasPixel}`);

const cnt = pd.ad_count;
let tier = '';
let priority = 'LOW';
let reason = '';

if (hasWhatsApp && hasCommercialWebsite) {
  tier = 'TIER_1';
  priority = 'HIGH';
  reason = 'WhatsApp + Commercial Website';
} else if (hasWhatsApp && hasPricing) {
  tier = 'TIER_1';
  priority = 'HIGH';
  reason = 'WhatsApp + Pricing Info';
} else if (hasWhatsApp && cnt >= 2) {
  tier = 'TIER_1';
  priority = 'HIGH';
  reason = 'WhatsApp + Multiple Ads';
} else if (hasCommercialWebsite && hasPricing) {
  tier = 'TIER_1';
  priority = 'HIGH';
  reason = 'Website + Pricing Info';
} else if (hasCommercialWebsite) {
  tier = 'TIER_1';
  priority = 'MEDIUM';
  reason = 'Has Commercial Website';
} else if (hasWhatsApp) {
  tier = 'TIER_1';
  priority = 'MEDIUM';
  reason = 'Has WhatsApp Contact';
} else if (hasDMPrice) {
  tier = 'TIER_1';
  priority = 'MEDIUM';
  reason = 'DM for Price (Potential WhatsApp)';
} else if (hasLocation && cnt >= 2) {
  tier = 'TIER_1';
  priority = 'MEDIUM';
  reason = 'Physical Location + Multiple Ads';
} else if (cnt >= 3) {
  tier = 'TIER_1';
  priority = 'MEDIUM';
  reason = 'Running 3+ Ads (Active Marketer)';
} else if (hasInstagram && hasPricing) {
  tier = 'TIER_2';
  priority = 'LOW';
  reason = 'Instagram + Pricing';
} else if (hasInstagram && cnt >= 2) {
  tier = 'TIER_2';
  priority = 'LOW';
  reason = 'Instagram + Multiple Ads';
} else if (hasPricing) {
  tier = 'TIER_2';
  priority = 'LOW';
  reason = 'Shows Pricing Info';
} else if (cnt >= 2) {
  tier = 'TIER_2';
  priority = 'LOW';
  reason = 'Running 2+ Ads';
} else if (hasFacebookPage) {
  tier = 'TIER_2';
  priority = 'LOW';
  reason = 'Active Facebook Page';
} else {
  tier = 'TIER_3';
  priority = 'LOWEST';
  reason = 'Single Ad, Minimal Signals (Review Manually)';
}

let vol = 0;
if (cnt >= 50) vol = 30;
else if (cnt >= 25) vol = 25;
else if (cnt >= 12) vol = 20;
else if (cnt >= 6) vol = 15;
else if (cnt >= 3) vol = 10;
else if (cnt >= 2) vol = 5;
else vol = 2;

const len = allBodies.length;
let soph = 0;
if (len > 500) soph += 8;
else if (len > 200) soph += 5;
else if (len > 100) soph += 3;
else if (len > 50) soph += 1;

const variationCount = (pd.all_bodies || []).length;
if (variationCount >= 5) soph += 8;
else if (variationCount >= 3) soph += 5;
else if (variationCount >= 2) soph += 2;

if (html.length > 0 && html.includes('<img')) soph += 6;
soph = Math.min(soph, 22);

let long = 0;
if (pd.earliest_start) {
  try {
