// ============================================================================
// COMBINE HTML WITH PAGE DATA - NEW NODE
// Purpose: Restore page data lost by HTTP node
// Mode: Run Once for All Items ✅ (CRITICAL)
// Reference: https://community.n8n.io/t/retaining-data-after-http-nodes/32066
// ============================================================================

const allItems = $input.all();
const output = [];

// Get the input data from "Preserve Page Data Before HTTP" node
// This was the input TO the HTTP node (contains page data)
const preservedData = $('Preserve Page Data Before HTTP').all();

console.log(`🔄 Combining ${allItems.length} HTTP responses with page data`);

for (let i = 0; i < allItems.length; i++) {
  const httpResult = allItems[i];
  const pageData = preservedData[i].json;  // Get corresponding page data

  // Extract HTML from binary
  let htmlContent = '';
  let htmlFetchError = false;

  if (httpResult.binary && httpResult.binary.data && httpResult.binary.data.data) {
    try {
      htmlContent = Buffer.from(httpResult.binary.data.data, 'base64').toString('utf-8');
      console.log(`✅ Extracted HTML for "${pageData.page_name}": ${htmlContent.length} chars`);
    } catch(e) {
      console.error(`❌ Failed to extract HTML for "${pageData.page_name}":`, e.message);
      htmlFetchError = true;
    }
  } else {
    console.warn(`⚠️ No HTML binary data for "${pageData.page_name}"`);
    htmlFetchError = true;
  }

  // Check for HTTP errors
  if (httpResult.json && httpResult.json.error) {
    htmlFetchError = true;
  }

  // Combine page data with HTML
  output.push({
    json: {
      // All page data fields
      ...pageData,

      // HTML fields
      html_content: htmlContent,
      html_length: htmlContent.length,
      html_fetch_error: htmlFetchError,
      html_fetch_attempted: true,
      _html_source: 'HTTP_FETCH'
    }
  });
}

