const items = $input.all();
const output = [];

for (const item of items) {
  const data = item.json;

  // Get HTML content
  const html = data.htmlcontent || '';
  const htmlLower = html.toLowerCase();

  // Skip if no HTML or already has phone from ads
  if (!html || html.length < 100) {
    output.push({ json: data });
    continue;
  }

  console.log(`🔍 Extracting contacts from HTML for: ${data.pagename}`);

  // ============================================
  // PHONE NUMBER EXTRACTION FROM HTML
  // ============================================

  let extractedPhone = null;
  let extractedWhatsApp = null;

  // Pattern 1: WhatsApp links in HTML
  const waLinkPatterns = [
    /wa\.me\/(\+?91)?(\d{10})/gi,
    /api\.whatsapp\.com\/send\?phone=(\+?91)?(\d{10})/gi,
    /whatsapp:\/\/send\?phone=(\+?91)?(\d{10})/gi
  ];

  for (const pattern of waLinkPatterns) {
    const matches = html.matchAll(pattern);
    for (const match of matches) {
      const number = match[2] || match[1];
      if (number && /^[6-9]\d{9}$/.test(number)) {
        extractedPhone = number;
        extractedWhatsApp = `https://wa.me/91${number}`;
        console.log(`✅ Found WhatsApp in HTML: ${number}`);
        break;
      }
    }
    if (extractedPhone) break;
  }

  // Pattern 2: Phone numbers in text content (if WhatsApp not found)
  if (!extractedPhone) {
    const phonePatterns = [
      // Format: +91-9876543210 or +919876543210
      /\+91[-\s]?([6-9]\d{9})/g,
      // Format: 91-9876543210 or 919876543210
      /\b91[-\s]?([6-9]\d{9})/g,
      // Format: 9876543210 (standalone 10 digits)
      /\b([6-9]\d{9})\b/g,
      // Format: 98765-43210 or 98765 43210
      /\b([6-9]\d{4})[-\s]?(\d{5})\b/g
    ];

    for (const pattern of phonePatterns) {
      const matches = html.matchAll(pattern);
      for (const match of matches) {
        let number;

        // Handle grouped patterns (98765-43210)
        if (match.length === 3) {
          number = match[1] + match[2];
        } else {
          number = match[1];
        }

        // Validate: must start with 6-9 and be exactly 10 digits
        if (number && /^[6-9]\d{9}$/.test(number)) {
          extractedPhone = number;
          extractedWhatsApp = `https://wa.me/91${number}`;
          console.log(`✅ Found phone in HTML: ${number}`);
          break;
        }
      }
      if (extractedPhone) break;
    }
  }

  // Pattern 3: Extract from tel: links
  if (!extractedPhone) {
    const telPattern = /href=["']tel:(\+?91)?[-\s]?([6-9]\d{9})["']/gi;
    const telMatches = html.matchAll(telPattern);
    for (const match of telMatches) {
      const number = match[2];
      if (number && /^[6-9]\d{9}$/.test(number)) {
        extractedPhone = number;
        extractedWhatsApp = `https://wa.me/91${number}`;
        console.log(`✅ Found tel: link in HTML: ${number}`);
        break;
      }
    }
  }

  // Pattern 4: Look in onclick/data attributes
  if (!extractedPhone) {
    const attrPattern = /(?:onclick|data-phone|data-mobile)=["'][^"']*?(\+?91)?[-\s]?([6-9]\d{9})[^"']*?["']/gi;
    const attrMatches = html.matchAll(attrPattern);
    for (const match of attrMatches) {
      const number = match[2];
      if (number && /^[6-9]\d{9}$/.test(number)) {
        extractedPhone = number;
        console.log(`✅ Found phone in HTML attribute: ${number}`);
        break;
      }
    }
  }

  // ============================================
  // UPDATE DATA WITH EXTRACTED CONTACTS
  // ============================================

  // Priority: Keep existing phone from ads if HTML extraction failed
  const finalPhone = extractedPhone || data.phonenumber;
  const finalWhatsApp = extractedWhatsApp || data.whatsappurl;

  // Log extraction results
  if (extractedPhone && !data.phonenumber) {
    console.log(`🎯 NEW phone found in HTML: ${extractedPhone}`);
  } else if (extractedPhone && data.phonenumber && extractedPhone !== data.phonenumber) {
    console.log(`⚠️ HTML phone (${extractedPhone}) differs from ad phone (${data.phonenumber})`);
  }

  // Output with updated fields
  output.push({
    json: {
      ...data,
      // Update phone/WhatsApp if found in HTML
      phonenumber: finalPhone,
      whatsappurl: finalWhatsApp,
      whatsappnumber: finalPhone || data.whatsappnumber
    }
  });
}

