// ============================================
// PARSE INSTAGRAM FROM AD SNAPSHOT HTML
// Mode: Run Once for Each Item
// Purpose: Extract Instagram profile links from Facebook ad preview pages
// Updated: Feb 13, 2026 - FIXED for snake_case field names
// ============================================

const item = $input.item.json;
const originalData = item._originaldata || {};

// Extract HTML from HTTP response
// n8n 2.0+ stores text responses in 'data' field
let html = '';
let fetchError = false;

if (item.data && typeof item.data === 'string') {
  html = item.data;
} else if (item.body && typeof item.body === 'string') {
  html = item.body;
} else if (item.error) {
  console.warn(`❌ HTTP fetch failed for ${originalData.page_name || 'Unknown'}: ${item.error}`);
  fetchError = true;
} else {
  console.warn(`⚠️  No HTML found for ${originalData.page_name || 'Unknown'}`);
  fetchError = true;
}

let instagram_url = null;
let instagram_handle = null;
let instagram_source = null;

if (html && html.length > 0) {
  console.log(`📄 Processing HTML for ${originalData.page_name} (${html.length} chars)`);

  // Instagram link patterns - ordered by reliability
  const patterns = [
    // Pattern 1: Direct profile links
    /https?:\/\/(?:www\.)?instagram\.com\/([a-zA-Z0-9._]{1,30})(?:\/|\?|$)/gi,

    // Pattern 2: Instagram redirect links (l.instagram.com)
    /https?:\/\/l\.instagram\.com\/[^\"'\s<>]+/gi,

    // Pattern 3: Encoded Instagram URLs
    /instagram\.com(?:%2F|\/)([a-zA-Z0-9._]{1,30})/gi,

    // Pattern 4: Visit Instagram button context
    /Visit Instagram[^<>]*?(?:href=\"([^\"]*instagram[^\"]*)\")/gi
  ];

  for (const pattern of patterns) {
    const matches = [...html.matchAll(pattern)];

    for (const match of matches) {
      let foundUrl = match[0];
      let foundHandle = match[1];

      // Skip if URL points to posts/reels/explore (we want profiles only)
      if (foundUrl.includes('/p/') || 
          foundUrl.includes('/reel/') || 
          foundUrl.includes('/explore/') ||
          foundUrl.includes('/stories/')) {
        continue;
      }

      // Handle l.instagram.com redirects (these are valid profile links)
      if (foundUrl.includes('l.instagram.com')) {
        // Keep the redirect URL as-is, extract destination if possible
        const destMatch = foundUrl.match(/u=([^&]+)/);
        if (destMatch) {
          try {
            const decoded = decodeURIComponent(destMatch[1]);
            const handleMatch = decoded.match(/instagram\.com\/([a-zA-Z0-9._]+)/);
            if (handleMatch) {
              foundHandle = handleMatch[1];
            }
          } catch(e) {}
        }
        instagram_url = foundUrl;
        instagram_handle = foundHandle;
        instagram_source = 'ad_snapshot_redirect';
        console.log(`✅ Found Instagram redirect: ${foundUrl}`);
        break;
      }

      // Validate handle format (1-30 chars, alphanumeric + underscore + period)
      if (foundHandle && /^[a-zA-Z0-9._]{1,30}$/.test(foundHandle)) {
        // Skip generic/placeholder handles
        const skipHandles = ['instagram', 'explore', 'accounts', 'direct'];
        if (!skipHandles.includes(foundHandle.toLowerCase())) {
          instagram_url = `https://www.instagram.com/${foundHandle}`;
          instagram_handle = foundHandle;
          instagram_source = 'ad_snapshot';
          console.log(`✅ Found Instagram profile: @${foundHandle}`);
          break;
        }
      }
    }

    if (instagram_url) break;
  }

  if (!instagram_url) {
    console.log(`❌ No Instagram found for ${originalData.page_name}`);
  }
} else if (!fetchError) {
  console.warn(`⚠️  Empty HTML for ${originalData.page_name}`);
}

// Return merged data with snake_case field names
return {
  json: {
    // Original ad data
    ...originalData,

    // Instagram extraction results
    instagram_url: instagram_url,
    instagram_handle: instagram_handle,
    instagram_source: instagram_source,

    // Metadata
    _snapshot_html_length: html.length,
    _snapshot_fetch_error: fetchError,
    _snapshot_checked: true
  }
};
